import{z as i,x as s,o as e,c as d,q as l,j as n,D as a,d as A,s as o,S as r,b as B}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"香港市场","description":"","frontmatter":{"title":"香港市场","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-hongkong.md","filePath":"quant/gm-hongkong.md","lastUpdated":1791413859000}'),p={name:"quant/gm-hongkong.md"};function C(D,E,m,u,h,S){const t=s("Mermaid");return e(),d("div",null,[E[2]||(E[2]=l('<h1 id="香港市场" tabindex="-1">香港市场 <a class="header-anchor" href="#香港市场" aria-label="Permalink to &quot;香港市场&quot;">​</a></h1><div class="epigraph"><p>港股是「单主场、高税费、硬约束」的组合：没有订单保护，卖空要过清单，双边印花税先于价差入账——在港股，策略的第一道门槛是一道税负题。</p><footer>—— 据 HKEX 公开交易规则（收市竞价 CAS 与 VCM 条文、卖空指定证券安排）及印花税条例口径整理</footer></div><p><a href="/quant/gm-japan">上一课</a>写日本如何把快引擎与旧参数表放进同一张订单。香港回单主场结构：一家交易所承接绝大多数现货，场所间竞争问题几乎不存在；真正约束策略的是三件事——尾盘的波动控制、卖空的清单化、以及双边印花税对换手成本的抬高。本课写这套组合拳的机制含义，并交代互联互通通道带来的日历问题。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>港股的第一缺口在成本结构：名义价差之外，买卖双边各有一道印花税，近年来先调高后调减——对高频与高换手策略，税费常大于价差本身，「价差即成本」的直觉在这里直接失效。第二缺口在尾盘：收市竞价（CAS）重启后以波动控制机制（VCM）框住竞价价格带，触发即冷静期，收盘价的生成过程被制度化——尾盘执行的基准与「最后几分钟随便打」的假设不同。第三缺口在做空：只有指定清单内的证券可卖空，卖空须先借券（covered），且受不得低于最优买价的 tick rule 约束——卖空从权利变成逐日维护的清单与借券管理。第四缺口在通道：南北向互联互通让同一只股票有两个可交易日历与两种货币腿，通道任一侧休市时，另一侧的持仓风险无人对冲。</p><p><span class="marginnote">交易日历错位是港股特有的一阶风险：南向或北向任一侧假日，通道闭市，而标的的基本面信息不会等日历——配对簿要在「两边同时可交易」的日历上对齐，只在时钟上对齐是不够的。</span></p><p><span class="marginnote">数字实例：印花税按成交额双边征收。一笔 100 万港元的买入加一笔等额卖出，仅印花税一项按 0.1%（历史水平，后有调减）就是买卖各 1000 港元、往返 2000 港元，占本金 0.2%；若策略日均换手一次、毛利预期 0.15%，那么税比毛利还宽——这就是「价差即成本」的直觉在港股失效的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单法照旧，四项入表。撮合与尾盘：连续时段进中央撮合簿，收盘经收市竞价生成；VCM 的带内监测与冷静期写入尾盘执行模型——尾盘 TCA 的基准是「带约束的竞价收盘」，不是理论末价。港交所近年还把部分场外配对收进受监管的撮合设施（OMP 一类），让交易所簿外的成交也留下更完整的磁带痕迹——数据覆盖口径要跟着扩。费用：印花税、平台费、结算费逐边入表，任何换手敏感的回测先做税负敏感性。卖空：可用集按「指定清单、借券可得、tick rule」三重过滤，借券费与可用量随时间变动，作为状态变量建模。通道：南北向的标的范围、额度与汇率腿单列，通道关闭日按不可交易处理。</p><p><span class="marginnote">「tick rule」翻译成白话：卖空价不得低于当时的最佳买价（或最后成交价，视规则版本）。它是给做空加的「限速带」——防止卖空者一路往下压价砸盘。实务后果是：快速下跌的市场里卖空单经常挂不上、只能等反弹挂更高价，空腿的成交时点因此系统性偏晚，回测要把这条延迟算进去。</span></p>',10)),(e(),n(r,null,{default:a(()=>[o(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMS%5B%22%E8%BF%9E%E7%BB%AD%E6%97%B6%E6%AE%B5%E4%B8%AD%E5%A4%AE%E6%92%AE%E5%90%88%22%5D%20--%3E%20CAS%5B%22%E6%94%B6%E5%B8%82%E7%AB%9E%E4%BB%B7%20CAS%22%5D%0A%20%20CAS%20--%3E%20VCM%5B%22VCM%20%E4%BB%B7%E6%A0%BC%E5%B8%A6%E4%B8%8E%E5%86%B7%E9%9D%99%E6%9C%9F%22%5D%0A%20%20CMS%20--%3E%20SSE%5B%22%E5%8D%96%E7%A9%BA%EF%BC%9A%E6%8C%87%E5%AE%9A%E6%B8%85%E5%8D%95%20%2B%20%E5%80%9F%E5%88%B8%20%2B%20tick%20rule%22%5D%0A%20%20SSE%20--%3E%20SET2%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E9%9B%86%E6%94%B6%E7%BC%A9%22%5D%0A%20%20CMS%20--%3E%20STAMP%5B%22%E5%8F%8C%E8%BE%B9%E5%8D%B0%E8%8A%B1%E7%A8%8E%22%5D%0A%20%20STAMP%20--%3E%20COST%5B%22%E6%8D%A2%E6%89%8B%E6%88%90%E6%9C%AC%E6%8A%AC%E5%8D%87%22%5D%0A%20%20STK%5B%22%E4%BA%92%E8%81%94%E4%BA%92%E9%80%9A%EF%BC%9A%E5%8D%97%E5%90%91%E4%B8%8E%E5%8C%97%E5%90%91%22%5D%20--%3E%20CAL%5B%22%E6%97%A5%E5%8E%86%E9%94%99%E4%BD%8D%E4%B8%8E%E6%B1%87%E7%8E%87%E8%85%BF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[A("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"三个机制的共同点是把「自由变量」变成「状态变量」。VCM 把尾盘从市价单竞赛改写成带内排队加冷静期：收盘价更稳，但尾盘流动性的时间分布改变，把执行算法的尾盘参数从美股搬来会系统性错配。卖空的清单化改变截面：不可卖空的「贵」证券缺乏纠偏力量，多空组合的空腿要在清单内重新定义——「模型说空」与「制度允许空」是两个集合。印花税的机制效果最直接：双边比例税等价于对换手率征线性惩罚，策略在美股样本的费后排序不能平移到港股，必须重排（税的一般机制在税与交易成本课展开）。通道的机制效果是同一风险资产的分割定价：两边的资金结构与约束不同，折溢价成为常态，通道状态（开、闭、额度）是定价状态的一部分。",-1)),E[5]||(E[5]=B("p",null,"VCM 在尾盘如何把一段失控下跌变成「触发—冷静—恢复」的循环，这条时间线回答的是「收盘价为什么是被制度框着生成的」：",-1)),(e(),n(r,null,{default:a(()=>[o(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E5%B0%BE%E7%9B%98%E7%AB%9E%E4%BB%B7%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20Band%5B%22%E4%BB%B7%E6%A0%BC%E5%B8%A6%20%E4%BB%A5%E5%8F%82%E8%80%83%E4%BB%B7%E4%B8%BA%E4%B8%AD%E5%BF%83%22%5D%0A%20%20T0%20--%3E%20Move%7B%22%E6%88%90%E4%BA%A4%E4%BB%B7%E8%A7%A6%E5%8F%8A%E5%B8%A6%E8%BE%B9%3F%22%7D%0A%20%20Move%20--%20%22%E5%90%A6%22%20--%3E%20Normal%5B%22%E6%AD%A3%E5%B8%B8%E7%AB%9E%E4%BB%B7%E8%87%B3%E6%94%B6%E7%9B%98%22%5D%0A%20%20Move%20--%20%22%E6%98%AF%22%20--%3E%20Halt%5B%22%E8%A7%A6%E5%8F%91%20VCM%20%E8%BF%9B%E5%85%A5%E5%86%B7%E9%9D%99%E6%9C%9F%22%5D%0A%20%20Halt%20--%3E%20Pause%5B%22%E6%9A%82%E5%81%9C%E6%88%90%E4%BA%A4%20%E8%AE%A9%E4%BF%A1%E6%81%AF%E6%B6%88%E5%8C%96%22%5D%0A%20%20Pause%20--%3E%20Reopen%5B%22%E6%81%A2%E5%A4%8D%E7%AB%9E%E4%BB%B7%20%E5%B8%A6%E9%87%8D%E6%96%B0%E8%AE%A1%E7%AE%97%22%5D%0A%20%20Reopen%20--%3E%20Move%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=l('<p><span class="marginnote">常见误区：初学者容易把 VCM 冷静期当成「跌停板」——其实它不禁止价格最终走到任何位置，只是暂停几分钟让订单重新排队。把港股尾盘当美股尾盘执行（最后几分钟猛打市价单），很可能在触发冷静期后干等，错过计划中的收盘成交量。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>港股通标的与本地全市场的可交易集不同，用哪个集合回测要先声明；权证与牛熊证的流通量提供者报价义务不等于正股流动性，衍生权证市场不进本课口径。IPO 结算平台、大宗机制等发行侧制度不写。具体税率、带值与时段以 HKEX 与税例当期文本为准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>港股的第一道成本是双边印花税，换手敏感策略先过税负敏感性。</li><li>收盘价由带 VCM 约束的收市竞价生成，尾盘执行与 TCA 按此基准。</li><li>卖空是「指定清单、先借券、tick rule」的三重过滤状态，不是默认权利。</li><li>南北向通道带来双日历与汇率腿，敞口要在两边同时可交易的日历上对齐。</li><li>出处：HKEX 公开交易规则（CAS 与 VCM、卖空指定证券安排）；印花税条例口径；据本课程执行与费用各课整理。</li></ul>',5))])}const _=i(p,[["render",C]]);export{T as __pageData,_ as default};
